import{_ as i,o,c as a,j as e}from"./chunks/framework.8tqBsFWt.js";const m=JSON.parse(`{"title":"The Briefing That Replaced the Monday Check-in","description":"The morning summary now answers two questions simultaneously: what am I supposed to be working on, and where do my projects stand?","frontmatter":{"title":"The Briefing That Replaced the Monday Check-in","date":"2026-03-24","series":"Features","description":"The morning summary now answers two questions simultaneously: what am I supposed to be working on, and where do my projects stand?","sidebar":false,"prev":false,"next":false},"headers":[],"relativePath":"blog/19-the-briefing.md","filePath":"blog/19-the-briefing.md","blogPosts":[{"url":"/blog/23-confidently-wrong","fm":{"title":"Confidently Wrong","date":"2026-05-28","series":"AI Behaviour","description":"The most dangerous answer a system can give isn't \\\\\\"I don't know\\\\\\" — it's a confident answer about a world that has already changed. We spent a week teaching VERA the difference between what it remembers and what's true."}},{"url":"/blog/22-getvera-site","fm":{"title":"A Proper Address","date":"2026-04-18","series":"Infrastructure","description":"VERA now lives at getvera.site. The old GitHub Pages URL redirects automatically — but the address a prospect reads on a pricing page is part of the pitch."}},{"url":"/blog/21-not-everyone-works-forty-hours","fm":{"title":"Not Everyone Works Forty Hours","date":"2026-03-29","series":"Features","description":"Capacity planning only works if the system knows how each person actually works. VERA was treating your contractors like full-time employees. It no longer does."}},{"url":"/blog/20-when-done-means-done","fm":{"title":"When Done Means Done","date":"2026-03-25","series":"AI Behaviour","description":"A confirmation that nothing happened behind it is worse than no confirmation at all. We fixed the moment where trust breaks."}},{"url":"/blog/19-the-briefing","fm":{"title":"The Briefing That Replaced the Monday Check-in","date":"2026-03-24","series":"Features","description":"The morning summary now answers two questions simultaneously: what am I supposed to be working on, and where do my projects stand?"}},{"url":"/blog/18-sheets-formulas-as-code","fm":{"title":"Building the Dashboard the Owner Actually Needs","date":"2026-03-15","series":"Data Model","description":"A live dashboard that answers the real questions: which projects are healthy, which are at risk, and what the business earned this month."}},{"url":"/blog/17-two-spreadsheets","fm":{"title":"The Dashboard Is Always Current","date":"2026-03-13","series":"Architecture","description":"The client''s reporting view and the database are separate spreadsheets. The client can never accidentally break the data — and they never have to request a report."}},{"url":"/blog/16-column-order-is-the-api","fm":{"title":"The Invisible Contract in the Spreadsheet","date":"2026-03-12","series":"Data Model","description":"Google Sheets doesn''t enforce its own structure. We had to. The rules we built to keep the data trustworthy."}},{"url":"/blog/14-agile-as-billing-model","fm":{"title":"Agile as a Billing Model","date":"2026-03-08","series":"Business Logic","description":"A sprint is a delivery unit and a revenue recognition unit. Timeliness of logging determines timeliness of revenue — they''re the same thing."}},{"url":"/blog/15-ooo-is-a-financial-event","fm":{"title":"Absence Is Data Too","date":"2026-03-08","series":"Business Logic","description":"Time off is a cost. If it doesn''t appear in the same system as time worked, the capacity picture is wrong and the P&L is incomplete."}},{"url":"/blog/13-design-md-rethink","fm":{"title":"Writing It Down Made Us Confront What We''d Built","date":"2026-03-07","series":"Architecture","description":"Six weeks in, we stopped and wrote down every decision we''d made. Several of them turned out to be wrong."}},{"url":"/blog/12-phased-expansion","fm":{"title":"What Becomes Possible When the Data Is Real","date":"2026-03-03","series":"Features","description":"Once time tracking is accurate and timely, a layer of project intelligence that was previously impossible becomes straightforward."}},{"url":"/blog/11-multi-tenancy-bugs","fm":{"title":"Reliability Is the Promise","date":"2026-03-01","series":"Architecture","description":"Timeliness only works if the system is there when the moment arrives. Getting multi-tenant reliability right was non-negotiable."}},{"url":"/blog/10-multi-tenancy","fm":{"title":"Each Client Gets Their Own VERA","date":"2026-02-25","series":"Architecture","description":"Multi-tenancy wasn''t a feature request. It was the point. A tool that feels shared feels like someone else''s."}},{"url":"/blog/09-timebot-becomes-vera","fm":{"title":"TimeBot Becomes VERA","date":"2026-02-22","series":"Origins","description":"A name signals a relationship. We weren''t building a utility."}},{"url":"/blog/07-retainers-are-weird","fm":{"title":"Retainers Without Timely Data Are Just Guesses","date":"2026-02-19","series":"Business Logic","description":"A retainer is a commitment to deliver a volume of work within a period. If you don''t know where you are until the invoice, you''ve already lost."}},{"url":"/blog/08-snapshots-version-control-spreadsheet","fm":{"title":"The Business Was There Last Tuesday Too","date":"2026-02-19","series":"Infrastructure","description":"When data is live and timely, the next question is whether you can go back. We built that in from the start."}},{"url":"/blog/06-roles-and-dollars","fm":{"title":"The Data Is Only Worth Protecting If It''s Worth Something","date":"2026-02-17","series":"Permissions","description":"When the data is timely and accurate, the financial numbers become real. Real numbers need to reach the right people — and not the wrong ones."}},{"url":"/blog/04-schema-grows-up","fm":{"title":"Making a Slack Message Do the Work of a Form","date":"2026-02-12","series":"Data Model","description":"We removed the interface. That meant every piece of information the owner needed had to be captured from a casual Slack message without making that message any harder to send."}},{"url":"/blog/05-prompt-engineering-wars","fm":{"title":"The Clarifying Questions Problem","date":"2026-02-12","series":"AI Behaviour","description":"Timeliness is the whole product. Any friction that risks the timing is a product failure."}},{"url":"/blog/03-socket-mode-railway","fm":{"title":"The Deployment That Didn''t Require a Web App","date":"2026-02-11","series":"Infrastructure","description":"We needed to deploy without adding anything to the client''s stack. Socket Mode and Railway made that possible for almost nothing."}},{"url":"/blog/01-the-problem","fm":{"title":"The Problem That Made VERA Necessary","date":"2026-02-10","series":"Origins","description":"Every time tracking tool ever built starts from the wrong assumption. We found the one thing that fixes it."}},{"url":"/blog/02-day-one-slack-claude-sheets","fm":{"title":"Day One: Slack → Claude → Google Sheets","date":"2026-02-10","series":"Origins","description":"The three components we chose on day one — and why each one was chosen specifically because it required no new interface."}}]}`),s={name:"blog/19-the-briefing.md"};function n(r,t,l,h,d,c){return o(),a("div",null,[...t[0]||(t[0]=[e("p",null,"The Monday morning check-in exists for one reason. Everyone needs two things at the start of the week: what they are supposed to be working on, and where the work actually stands. The meeting exists because there is no other way to get that information quickly.",-1),e("p",null,"VERA's morning summary now does both, automatically, before the working day starts.",-1),e("p",null,"For each team member, the briefing includes a table of their active allocations: project, task type, total hours allocated, hours logged so far, and hours remaining. It is not a reminder. It is a statement of record. You know exactly what you are supposed to deliver, and you know exactly how much of it is already done. No conversation required.",-1),e("p",null,"For each project manager, the briefing includes every project they manage plotted against an ideal burn-down line. The logic is simple: if a project has a 10-hour budget and a 10-day window, the expectation is one hour per day. On day six, the project should have six hours in it. If it has four, it is two hours behind the line. If it has eight, it is two hours ahead. VERA surfaces the variance directly — ahead, on track, behind, or significantly behind — sorted so the most off-track project is always first.",-1),e("p",null,"That is the conversation that used to happen in the Monday meeting. Now it happens before anyone arrives.",-1),e("p",null,"The pace forecast sits alongside it. Where linear progress tells you where a project stands today, pace tells you which direction it is moving. A project can be slightly behind but accelerating — closing the gap, unlikely to be a problem. The same variance on a project that has gone quiet for two weeks is a completely different situation. Both pieces of information matter, and the combination of them removes most of the ambiguity a PM would otherwise have to resolve by asking someone directly.",-1),e("p",null,"There is a timing argument here that is easy to miss. Burn-down position at nine on Monday morning is actionable. The same number delivered on Friday afternoon is a post-mortem. The briefing works not because the information is new, but because it arrives at the moment when something can still be done about it.",-1),e("p",null,"The other thing we decided: the two audiences see different things. Team members see their own allocations only — what they are expected to deliver. Managers see project health across their portfolio. The briefing is not a single message that gets sent to everyone; it is a personalised summary for each person, shaped by what their role actually requires them to do with the information.",-1),e("p",null,"That distinction matters. A team member does not need to know that the project is behind the burn-down line. That is the manager's problem to solve. Surfacing it to both would create noise for one and dilute responsibility for the other. The briefing is useful precisely because it gives each person only the information they are in a position to act on.",-1)])])}const p=i(s,[["render",n]]);export{m as __pageData,p as default};
